from django.contrib.contenttypes.models import ContentType
from rest_framework import viewsets, permissions
from rest_framework.exceptions import ValidationError, PermissionDenied
from django.core.exceptions import ObjectDoesNotExist
from .models import GenericActivityLog
from .serializers import ActivityLogSerializer

class GenericActivityLogViewSet(viewsets.ReadOnlyModelViewSet):
    serializer_class = ActivityLogSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        model_name = self.request.query_params.get('model')
        object_id = self.request.query_params.get('object_id')
        if not model_name or not object_id:
            raise ValidationError("Both 'model' and 'object_id' query parameters are required.")

        try:
            ct = ContentType.objects.get(model=model_name.lower())
            target_obj = ct.get_object_for_this_type(pk=object_id)
        except (ContentType.DoesNotExist, ObjectDoesNotExist):
            return GenericActivityLog.objects.none()

        if hasattr(target_obj, 'user') and target_obj.user != self.request.user:
            raise PermissionDenied("You do not have access to view audit trails for this object.")
        if hasattr(target_obj, 'organization') and target_obj.organization != self.request.user.organization:
            raise PermissionDenied("Cross-organization audit trail inspection is forbidden.")

        return GenericActivityLog.objects.filter(content_type=ct, object_id=object_id).order_by('-created_at')
